 * @param {string} texte La chaîne de caractères à analyser.
 * @param {number} n Le nombre exact de mots attendu.
 * @returns {boolean} True si le compte des mots est égal à N, false sinon.
 */
function verifierNombreDeMots(texte, n) {
    // 1. Supprimer les espaces au début et à la fin (trim).
    const texteNettoye = texte.trim();

    // Si le texte est vide après trim, il contient 0 mots.
    if (texteNettoye === "") {
        return n === 0;
    }

    // 2. Séparer les mots en utilisant une expression régulière pour gérer tous les espaces (\s+).
    const mots = texteNettoye.split(/\s+/);

    // 3. Comparer le nombre de mots au nombre attendu N.
    return mots.length === n;
}
```

