function rotationDroite(tab, k) {
    const n = tab.length;

    if (n === 0 || k % n === 0) {
        return [...tab]; // Retourne une copie si pas de rotation nécessaire ou le tableau est vide
    }

    // Calculer la rotation effective (k modulo N)
    const shift = k % n;

    // La partie qui doit aller au début est les 'shift' derniers éléments.
    // tab.slice(n - shift) prend les éléments de l'index (N-shift) jusqu'à la fin.
    const elementsFin = tab.slice(n - shift);

