    // tab.slice(0, n - shift) prend les éléments du début jusqu'à l'index (N-shift).
    const elementsDebut = tab.slice(0, n - shift);

    // Retourner le nouveau tableau concaténé
    return [...elementsFin, ...elementsDebut];
