 * @param {number} base - La base cible (entre 2 et 16).
 * @returns {string} La représentation de n en base 'base'.
 */
function convertirBase(n, base) {
    if (n === 0) return "0";
    if (base < 2 || base > 16) throw new Error("La base doit être entre 2 et 16.");

    const digits = "0123456789abcdef";
    let result = "";
    let currentN = n;

    while (currentN > 0) {
        // Calcul du reste pour obtenir le chiffre dans la nouvelle base.
        const remainder = currentN % base;
