/**
 * Calcule x à la puissance n (x^n) en utilisant l'exponentiation rapide (Exponentiation by Squaring).
 * @param {number} x - La base.
 * @param {number} n - L'exposant (doit être >= 0).
 * @returns {number} Le résultat de x^n.
 */
function exponentiationRapide(x, n) {
    if (n < 0) throw new Error("L'exposant doit être non négatif.");
    if (n === 0) return 1;
    if (n === 1) return x;

    // Implémentation itérative pour éviter les limites de la récursivité.
    let result = 1;
    let base = x;
    let power = n;

    while (power > 0) {
        // Si l'exposant est impair, on multiplie le résultat par la base actuelle.
        if (power % 2 === 1) {
            result *= base;
        }
        // On met au carré la base pour passer à la puissance supérieure de deux.
        base *= base;
        // On divise l'exposant par 2 (équivalent à un décalage binaire vers la droite).
        power = Math.floor(power / 2);
    }

    return result;
